python3 - <<'PY'
import json
import struct
import zlib

data = open('/app/sensor.log', 'rb').read()
by_offset = {}

for off in range(len(data) - 15):
    rec = data[off:off + 16]
    stored_crc = int.from_bytes(rec[12:16], 'little')
    if zlib.crc32(rec[:12]) & 0xffffffff != stored_crc:
        continue

    for endian in ('<', '>'):
        timestamp, sensor_id, reading_type, value = struct.unpack(endian + 'IHHf', rec[:12])

        if not (1600000000 <= timestamp <= 1800000000):
            continue
        if not (1 <= sensor_id <= 50):
            continue
        if reading_type not in (1, 2, 3):
            continue
        if reading_type == 1:
            in_range = 10.0 <= value <= 40.0
        elif reading_type == 2:
            in_range = 20.0 <= value <= 100.0
        else:
            in_range = 900.0 <= value <= 1100.0
        if not in_range:
            continue

        by_offset[off] = {
            'timestamp': timestamp,
            'sensor_id': sensor_id,
            'reading_type': reading_type,
            'value': round(value, 2),
        }

records = [by_offset[off] for off in sorted(by_offset)]
with open('/app/recovered.json', 'w') as f:
    json.dump(records, f, indent=2)
    f.write('\n')

print('recovered records:', len(records))
